// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BudgetNotice) predicate.BudgetNotice {
	return predicate.BudgetNotice(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BudgetNotice) predicate.BudgetNotice {
	return predicate.BudgetNotice(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BudgetNotice) predicate.BudgetNotice {
	return predicate.BudgetNotice(sql.NotPredicates(p))
}
